package com.lak.moviebooking.reporting.api;
import java.time.LocalDate; import java.util.UUID;
import com.lak.moviebooking.authorization.application.CinemaScopeAuthorizer; import com.lak.moviebooking.common.security.AuthenticatedPrincipal; import com.lak.moviebooking.reporting.application.ReportSummary; import com.lak.moviebooking.reporting.application.ReportingQuery;
import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/admin") public class ReportingController { private final ReportingQuery reports; private final CinemaScopeAuthorizer scope; public ReportingController(ReportingQuery reports,CinemaScopeAuthorizer scope){this.reports=reports;this.scope=scope;} @GetMapping("/reports/summary") public ReportSummary summary(@AuthenticationPrincipal AuthenticatedPrincipal actor,@RequestParam LocalDate from,@RequestParam LocalDate to,@RequestParam(required=false) UUID cinemaId){if(to.isBefore(from)||to.isAfter(from.plusDays(366)))throw new IllegalArgumentException("Invalid report date range");if(cinemaId!=null)scope.requireAccess(actor,cinemaId);return reports.summary(from,to,cinemaId,scope.accessibleCinemaIds(actor));} }
